    // Carousel
    (function() {
      const track = document.getElementById('carouselTrack');
      const slides = track.querySelectorAll('.carousel-slide');
      const dotsContainer = document.getElementById('carouselDots');
      let current = 0;
      let visibleCount = 3;

      function getVisible() {
        if (window.innerWidth <= 600) return 1;
        if (window.innerWidth <= 900) return 2;
        return 3;
      }

      function buildDots() {
        dotsContainer.innerHTML = '';
        visibleCount = getVisible();
        const total = slides.length - visibleCount + 1;
        for (let i = 0; i < total; i++) {
          const dot = document.createElement('button');
          dot.className = 'carousel-dot' + (i === current ? ' active' : '');
          dot.setAttribute('aria-label', 'Slide ' + (i + 1));
          dot.addEventListener('click', () => goTo(i));
          dotsContainer.appendChild(dot);
        }
      }

      function updateDots() {
        dotsContainer.querySelectorAll('.carousel-dot').forEach((d, i) => {
          d.classList.toggle('active', i === current);
        });
      }

      function goTo(idx) {
        visibleCount = getVisible();
        const max = slides.length - visibleCount;
        current = Math.max(0, Math.min(idx, max));
        const slideWidth = slides[0].offsetWidth;
        track.style.transform = `translateX(-${current * slideWidth}px)`;
        updateDots();
      }

      document.getElementById('carouselPrev').addEventListener('click', () => goTo(current - 1));
      document.getElementById('carouselNext').addEventListener('click', () => goTo(current + 1));

      // Touch / swipe
      let startX = 0;
      track.addEventListener('touchstart', e => { startX = e.touches[0].clientX; }, { passive: true });
      track.addEventListener('touchend', e => {
        const diff = startX - e.changedTouches[0].clientX;
        if (Math.abs(diff) > 40) goTo(current + (diff > 0 ? 1 : -1));
      });

      window.addEventListener('resize', () => { buildDots(); goTo(current); });
      buildDots();
    })();
  </script>
