  padding: 16px 40px;
  transition: background 0.2s, transform 0.2s, box-shadow 0.2s;
  cursor: pointer;
  border: none;
}
.btn-primary:hover {
  background: var(--red-dark);
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(255,0,0,0.3);
}

.btn-secondary {
  display: inline-block;
  background: transparent;
  color: #fff;
  font-family: 'Oswald', sans-serif;
  font-size: 0.95rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  padding: 14px 38px;
  border: 2px solid rgba(255,255,255,0.4);
  transition: border-color 0.2s, transform 0.2s;
  cursor: pointer;
}
.btn-secondary:hover {
  border-color: #fff;
  transform: translateY(-2px);
}

/* ── Navbar ── */
.navbar {
  position: fixed;
  top: 0; left: 0; right: 0;
  z-index: 1000;
  background: rgba(10, 10, 10, 0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
  transition: background 0.3s;
}
.navbar.scrolled { background: rgba(8, 8, 8, 0.98); }

.nav-inner {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 24px;
  height: 72px;
  display: flex;
  align-items: center;
  gap: 40px;
}

.nav-logo {
  font-family: 'Oswald', sans-serif;
  font-size: 1.6rem;
  font-weight: 700;
  text-transform: uppercase;
  color: #fff;
  letter-spacing: 0.05em;
  white-space: nowrap;
  flex-shrink: 0;
}
.nav-logo span { color: var(--red); }

.nav-links {
  list-style: none;
  display: flex;
  gap: 28px;
  flex: 1;
  align-items: center;
}
.nav-links a {
  font-family: 'Inter', sans-serif;
  font-size: 0.78rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: rgba(255,255,255,0.7);
  transition: color 0.2s;
  white-space: nowrap;
}
.nav-links a:hover,
.nav-links a.active { color: #fff; }

.nav-actions {
  display: flex;
  gap: 12px;
  align-items: center;
  flex-shrink: 0;
}

.btn-nav {
  font-family: 'Oswald', sans-serif;
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  padding: 10px 22px;
  background: var(--red);
  color: #fff;
  transition: background 0.2s;
  white-space: nowrap;
}
.btn-nav:hover { background: var(--red-dark); }
.btn-nav-outline {
  background: transparent;
  border: 1px solid rgba(255,255,255,0.3);
}
.btn-nav-outline:hover { background: rgba(255,255,255,0.08); }

.nav-hamburger {
  display: none;
  background: none;
  border: none;
  color: #fff;
  font-size: 1.6rem;
  cursor: pointer;
  margin-left: auto;
}

@media (max-width: 1100px) {
  .nav-links { gap: 18px; }
  .nav-links a { font-size: 0.72rem; }
}

@media (max-width: 960px) {
  .nav-hamburger { display: flex; align-items: center; }
  .nav-links {
    display: none;
    position: fixed;
    top: 72px; left: 0; right: 0;
    background: #0a0a0a;
    flex-direction: column;
    align-items: flex-start;
    padding: 24px 24px 32px;
    gap: 0;
    border-bottom: 1px solid var(--border);
  }
  .nav-links.open { display: flex; }
  .nav-links li { width: 100%; border-bottom: 1px solid var(--border); }
  .nav-links a { display: block; padding: 14px 0; font-size: 0.9rem; }
  .nav-actions { display: none; }
}

/* ── Page Hero (inner pages) ── */
.page-hero {
  padding: 160px 24px 80px;
  text-align: center;
  background: linear-gradient(180deg, #0a0a0a 0%, #141414 100%);
  position: relative;
  overflow: hidden;
}
.page-hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 60% 40% at 50% 30%, rgba(255,0,0,0.1) 0%, transparent 70%);
}
.page-hero-inner { position: relative; z-index: 1; max-width: 800px; margin: 0 auto; }
.page-hero-eyebrow {
  font-family: 'Inter', sans-serif;
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.25em;
  text-transform: uppercase;
  color: var(--red);
  margin-bottom: 20px;
}
.page-hero h1 {
  font-family: 'Oswald', sans-serif;
  font-size: clamp(2.5rem, 6vw, 5.5rem);
  font-weight: 700;
  text-transform: uppercase;
  line-height: 1;
  margin-bottom: 20px;
}
.page-hero p {
  font-size: 1.1rem;
  color: var(--text-muted);
  max-width: 600px;
  margin: 0 auto;
  line-height: 1.75;
}

/* ── Section heading ── */
.section-label {
  font-family: 'Inter', sans-serif;
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.25em;
  text-transform: uppercase;
  color: var(--red);
  margin-bottom: 16px;
}
.section-h2 {
  font-family: 'Oswald', sans-serif;
  font-size: clamp(2rem, 4vw, 3.5rem);
  font-weight: 700;
  text-transform: uppercase;
  color: #fff;
  margin-bottom: 24px;
  line-height: 1.05;
}
.section-body {
  font-size: 1.05rem;
  color: var(--text-muted);
  line-height: 1.8;
  max-width: 640px;
}

/* ── Newsletter ── */
.newsletter-section {
  padding: 100px 24px;
  background: #0d0d0d;
  text-align: center;
  border-top: 1px solid var(--border);
}
.newsletter-inner { max-width: 560px; margin: 0 auto; }
.newsletter-section h2 {
  font-family: 'Oswald', sans-serif;
  font-size: clamp(1.8rem, 3vw, 2.8rem);
  font-weight: 700;
  text-transform: uppercase;
  color: #fff;
  margin-bottom: 16px;
}
.newsletter-section p {
  font-size: 1rem;
  color: var(--text-muted);
  margin-bottom: 36px;
  line-height: 1.7;
}
.newsletter-form .newsletter-field {
  display: flex;
  gap: 0;
}
.newsletter-form input[type="email"] {
  flex: 1;
  background: #1a1a1a;
  border: 1px solid var(--border);
  border-right: none;
  color: #fff;
  font-family: 'Inter', sans-serif;
  font-size: 0.95rem;
  padding: 16px 20px;
  outline: none;
  transition: border-color 0.2s;
}
.newsletter-form input[type="email"]:focus { border-color: var(--red); }
.newsletter-form input[type="email"].error { border-color: #ff4444; }
.newsletter-form button {
  background: var(--red);
  color: #fff;
  font-family: 'Oswald', sans-serif;
  font-size: 0.9rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  padding: 16px 28px;
  border: none;
  cursor: pointer;
  transition: background 0.2s;
  white-space: nowrap;
}
.newsletter-form button:hover { background: var(--red-dark); }
.newsletter-error {
  color: #ff4444;
  font-size: 0.85rem;
  margin-top: 10px;
  min-height: 20px;
  text-align: left;
}
.newsletter-success {
  color: #4caf50;
  font-size: 0.9rem;
  margin-top: 12px;
  font-weight: 500;
  min-height: 20px;
}

@media (max-width: 500px) {
  .newsletter-form .newsletter-field { flex-direction: column; }
  .newsletter-form input[type="email"] { border-right: 1px solid var(--border); }
  .newsletter-form button { padding: 16px; }
}

/* ── Footer ── */
.site-footer {
  background: #0a0a0a;
  border-top: 1px solid var(--border);
  padding: 80px 24px 0;
}
.footer-inner {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 48px;
  padding-bottom: 64px;
  border-bottom: 1px solid var(--border);
}
@media (max-width: 900px) { .footer-inner { grid-template-columns: 1fr 1fr; } }
@media (max-width: 560px) { .footer-inner { grid-template-columns: 1fr; } }

.footer-logo .nav-logo { margin-bottom: 12px; }
.footer-logo p { font-size: 0.85rem; color: var(--text-muted); }

.footer-col h4 {
  font-family: 'Oswald', sans-serif;
  font-size: 0.85rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: rgba(255,255,255,0.4);
  margin-bottom: 20px;
}
.footer-col ul { list-style: none; }
.footer-col ul li { margin-bottom: 12px; }
.footer-col ul a {
  font-size: 0.88rem;
  color: rgba(255,255,255,0.6);
  transition: color 0.2s;
}
.footer-col ul a:hover { color: #fff; }

.footer-country {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 24px;
}
.footer-country i { color: var(--red); font-size: 1rem; }
.footer-country select {
  background: #1a1a1a;
  border: 1px solid var(--border);
  color: rgba(255,255,255,0.7);
  font-family: 'Inter', sans-serif;
  font-size: 0.85rem;
  padding: 8px 12px;
  cursor: pointer;
  outline: none;
}

.footer-bottom {
  max-width: 1200px;
  margin: 0 auto;
  padding: 28px 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
}
.footer-bottom p { font-size: 0.8rem; color: var(--text-muted); }
.footer-social { display: flex; gap: 16px; }
.footer-social a {
  color: rgba(255,255,255,0.4);
  font-size: 1.1rem;
  transition: color 0.2s;
}
.footer-social a:hover { color: var(--red); }

/* ── Divider line ── */
.red-line {
  width: 48px;
  height: 3px;
  background: var(--red);
  margin-bottom: 24px;
}

