  <script>
    // Instructor Location Filter
    (function() {
      var filterBtns = document.querySelectorAll('.filter-btn');
      var cards = document.querySelectorAll('.instructor-card');
      var countEl = document.getElementById('visibleCount');

      function updateCount() {
        var visible = document.querySelectorAll('.instructor-card:not([data-hidden="true"])').length;
        countEl.textContent = visible;
      }

      filterBtns.forEach(function(btn) {
        btn.addEventListener('click', function() {
          var loc = btn.getAttribute('data-location');
          filterBtns.forEach(function(b) { b.classList.remove('active'); });
          btn.classList.add('active');

          cards.forEach(function(card) {
            var cardLoc = card.getAttribute('data-location');
            var show = loc === 'all' || cardLoc === loc;
            card.setAttribute('data-hidden', show ? 'false' : 'true');
            card.style.display = show ? '' : 'none';
          });

          // No results check
          var grid = document.getElementById('instructorGrid');
          var existing = grid.querySelector('.no-results');
          var visible = document.querySelectorAll('.instructor-card:not([style*="display: none"])').length;
          if (visible === 0) {
            if (!existing) {
              var msg = document.createElement('div');
              msg.className = 'no-results';
              msg.innerHTML = '<i class="ri-user-search-line"></i>No instructors found for this location yet. Check back soon!';
              grid.appendChild(msg);
            }
          } else if (existing) {
            existing.remove();
          }
          updateCount();
        });
      });
    })();
  </script>
