      items.forEach(function(item) {
        var btn = item.querySelector('.accordion-btn');
        var body = item.querySelector('.accordion-body');
        var icon = item.querySelector('.accordion-icon i');

        btn.addEventListener('click', function() {
          var isOpen = btn.getAttribute('aria-expanded') === 'true';

          // Close all
          items.forEach(function(otherItem) {
            var ob = otherItem.querySelector('.accordion-btn');
            var obody = otherItem.querySelector('.accordion-body');
            var oicon = otherItem.querySelector('.accordion-icon i');
            ob.setAttribute('aria-expanded', 'false');
            obody.classList.remove('open');
            oicon.className = 'ri-add-line';
          });

          // Open clicked if it was closed
          if (!isOpen) {
            btn.setAttribute('aria-expanded', 'true');
            body.classList.add('open');
            icon.className = 'ri-close-line';
          }
        });
